/static/settings.js.body:
import { t } from "./i18n.js";

const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? "").replace(/[<>&"]/g, (c) => `&#${c.charCodeAt(0)};`);
// A list of names in the page's language: "A, B" and "A, B and C".
const list = (items) => items.reduce((head, item) => t("settings.list_more", {head, item}));
const listJoin = (items) => items.length < 2 ? items.join("")
  : t("settings.list_last", {head: list(items.slice(0, -1)), last: items.at(-1)});
let state = null;

const TABS = ["model", "digest", "pipeline", "notifications", "sources", "tracking"];
const SETTINGS_NOTICES = ["model-result", "digest-result", "pipeline-result", "notify-result"];

// The category lives in the hash, not the path: the Worker guards /settings by
// exact match, and a hash never leaves the browser.
function route() {
  const hash = location.hash.slice(1);
  const tab = TABS.includes(hash) ? hash : "model";
  document.querySelectorAll(".tab").forEach((panel) => {
    panel.hidden = panel.dataset.tab !== tab;
  });
  document.querySelectorAll(".settings-nav a").forEach((link) => {
    if (link.dataset.tab === tab) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
  window.scrollTo(0, 0);
  const active = document.querySelector(".settings-nav a[aria-current]");
  const gutter = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--s-4"));
  active.parentElement.scrollLeft = active.offsetLeft - gutter;
}

addEventListener("hashchange", route);
route();

// A category's Save is live only while its form differs from what was last
// loaded or saved, or holds a missing setting it can save as it stands; the
// category list marks a form that differs with a dot.
const clean = new Map();
// A form whose save is in flight keeps its Save disabled and its notice.
const saving = new Set();
// Keyed by field, so a save can tell which part of its form changed.
const snapshot = (form) => Object.fromEntries([...form.querySelectorAll("input, select, textarea")]
  .map((input) => input.type === "radio"
    ? [`${input.name}=${input.value}`, input.checked]
    : [input.id, input.value]));
const saveButton = (form) => form.querySelector('button[type="submit"]');
const navLink = (form) => document.querySelector(`.settings-nav a[data-tab="${form.dataset.tab}"]`);

// The Model form saves in two parts, each through its own route.
const LLM_PART = (field) => field.startsWith("provider=") || field === "model-input";
const VOTE_PART = (field) => !LLM_PART(field);
const partChanged = (form, part) => {
  const now = snapshot(form), stored = clean.get(form) || now;
  return Object.keys(now).some((field) => part(field) && now[field] !== stored[field]);
};

function refresh(form) {
  const dirty = clean.has(form)
    && JSON.stringify(snapshot(form)) !== JSON.stringify(clean.get(form));
  // With no provider chosen, there is nothing a model could be checked against.
  const blocked = form.dataset.tab === "model" && partChanged(form, LLM_PART) && !chosen();
  const pending = clean.has(form) && unsavedIn(form).length > 0;
  saveButton(form).disabled = !(dirty || pending) || blocked || saving.has(form);
  navLink(form).classList.toggle("dirty", dirty);
}

function markClean(form, values = snapshot(form)) {
  clean.set(form, values);
  refresh(form);
}

// An edit makes the last result stale, so it goes; a deployment that cannot
// save never tracks, and its explanation stays.
function edited(form) {
  if (clean.has(form) && !saving.has(form)) form.querySelector(".actions-line .notice").hidden = true;
  refresh(form);
}

document.querySelectorAll("form.tab").forEach((form) => {
  form.addEventListener("input", (e) => { unrefuseEdited(e.target); edited(form); });
  form.addEventListener("change", (e) => { unrefuseEdited(e.target); edited(form); });
});

// Each runtime setting's field, from the server's registry: the category it sits
// in, the label a notice names it by, the controls marked while it is not set, and
// the route that saves it.
let FIELDS = {};
// The settings saved through /api/settings/values, by the id of their control.
let PLAIN = {};
const keysSavedBy = (route) => Object.keys(FIELDS).filter((key) => FIELDS[key].route === route);
// A missing setting the page already answers, an empty field such as Style or Email
// to, or a select showing its starting value, such as Summarize follow articles: on a
// first boot nothing has changed, yet it can be saved as it stands. Not the webhook, whose
// off is its own action, nor a model, which is saved with its provider.
const SENT_AS_SHOWN = ["plain", "email"];
const unsavedIn = (form) => state.sent_as_shown.filter((key) => state.missing.includes(key)
  && SENT_AS_SHOWN.includes(FIELDS[key].route) && form.contains($(FIELDS[key].controls[0])));

// A control's own placeholder, which a missing value covers with "Not set".
document.querySelectorAll("[placeholder]").forEach((el) => {
  el.dataset.placeholder = el.placeholder;
});

// A key this edition keeps the reader from changing, with its reason (ADR-0043).
const isLocked = (key) => Object.hasOwn(state.locked, key);

// Whether `el` is a control of a setting this deployment's home lacks.
const isMissing = (el) => Object.entries(FIELDS)
  .some(([key, field]) => field.controls.includes(el.id) && state.missing.includes(key));

function applyPlaceholder(el) {
  if (!("placeholder" in el)) return;
  el.placeholder = isMissing(el) ? t("settings.not_set") : el.dataset.placeholder || "";
}

// A missing key's field, its category's notice and its dot stay until a save
// stores it.
function markMissing() {
  const missing = new Set(state.missing);
  // A stored zone is no longer only the detected one.
  if (!missing.has("general.timezone")) $("timezone-detected").hidden = true;
  const byTab = {};
  for (const [key, field] of Object.entries(FIELDS)) {
    const unset = missing.has(key);
    field.controls.forEach((id) => {
      const el = $(id);
      if (unset) el.setAttribute("aria-invalid", "true");
      else if (!el.classList.contains("invalid")) el.removeAttribute("aria-invalid");
      applyPlaceholder(el);
    });
    byTab[field.tab] = byTab[field.tab] || [];
    if (unset && !byTab[field.tab].includes(field.label)) byTab[field.tab].push(field.label);
  }
  for (const [tab, labels] of Object.entries(byTab)) {
    const notice = $(`${tab}-missing`);
    notice.textContent = !labels.length ? "" : t("settings.missing_notice", {labels: list(labels)});
    notice.hidden = !labels.length;
    document.querySelector(`.settings-nav a[data-tab="${tab}"]`)
      .classList.toggle("missing", labels.length > 0);
  }
}

function markSet(keys) {
  state.missing = state.missing.filter((key) => !keys.includes(key));
  markMissing();
}

// The output languages, each stored as its BCP 47 tag and shown by the name
// languages.json gives it, in that file's order. A stored tag the list lacks is
// still a language the model is told to write in, so it stays an option of its
// own, shown as the tag, and a save that leaves the field alone keeps it.
function fillLanguages(select, languages, stored) {
  const options = languages.map(({tag, name}) => new Option(name, tag));
  if (stored != null && !languages.some(({tag}) => tag === stored)) {
    options.push(new Option(stored, stored));
  }
  select.replaceChildren(...options);
}

// The zone this browser reads its own clock in, or "" when it will not say.
function browserZone() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "";
  } catch {
    return "";
  }
}

// Every zone this browser knows, UTC, which some leave out, and the stored zone
// and this browser's own when the list lacks them, so a save that leaves the
// field alone keeps what was stored.
function fillTimezones(select, stored) {
  const known = typeof Intl.supportedValuesOf === "function" ? Intl.supportedValuesOf("timeZone") : [];
  const zones = new Set([...known, "UTC", stored, browserZone()].filter(Boolean));
  select.replaceChildren(...[...zones].sort().map((zone) => new Option(zone, zone)));
}

// A timezone with no stored value opens on this browser's own, marked as
// detected rather than stored; the form's Save then stores it.
function detectTimezone(form) {
  const zone = browserZone();
  if (state.values["general.timezone"] != null || !zone || isLocked("general.timezone")) return;
  $("timezone").value = zone;
  $("timezone-detected").hidden = false;
  refresh(form);
}

// A zone the reader picked is no longer the detected one.
$("timezone").addEventListener("change", () => { $("timezone-detected").hidden = true; });

function render() {
  const values = state.values;
  FIELDS = state.fields;
  PLAIN = Object.fromEntries(keysSavedBy("plain").map((key) => [FIELDS[key].controls[0], key]));
  // A locked key is not the reader's to set, so it is never marked missing nor sent as shown.
  state.missing = state.missing.filter((key) => !isLocked(key));
  $("providers").innerHTML = state.providers.map((p) => `
    <label class="choice${p.configured ? "" : " unavailable"}">
      <input type="radio" name="provider" value="${esc(p.name)}"
             ${p.name === values["llm_provider.provider"] && p.configured ? "checked" : ""}
             ${p.configured ? "" : "disabled"}>
      <span class="name">${esc(p.name === "none" ? t("provider.none") : p.name)}</span>
      ${p.name === "none" ? `<span class="label">${esc(t("settings.no_key_needed"))}</span>`
        : p.configured ? `<span class="label">${esc(t("settings.key_ready"))}</span>`
        : `<span class="label key-missing">${esc(t("settings.key_missing", {variable: p.env_var}))}</span>`}
    </label>`).join("");
  $("model-input").value = values["llm_provider.model"] ?? "";
  updateHint();
  $("providers").addEventListener("change", updateHint);
  // A missing key does not disable an embedder: with vote similarity off,
  // choosing one needs no call.
  $("embedding-providers").innerHTML = state.embedding_providers.map((p) => `
    <label class="choice">
      <input type="radio" name="embedding-provider" value="${esc(p.name)}"
             ${p.name === values["vote_similarity.provider"] ? "checked" : ""}>
      <span class="name">${esc(p.name)}</span>
      ${p.configured
        ? `<span class="label">${esc(t("settings.key_ready"))}</span>`
        : `<span class="label key-missing">${esc(t("settings.key_missing", {variable: p.env_var}))}</span>`}
    </label>`).join("");
  $("embedding-model-input").value = values["vote_similarity.model"] ?? "";
  updateEmbeddingHint();
  $("embedding-providers").addEventListener("change", updateEmbeddingHint);
  const enabled = values["vote_similarity.enabled"];
  if (enabled == null) $("vote-enabled").prepend(new Option(t("settings.not_set"), "", true, true));
  else $("vote-enabled").value = String(enabled);
  if (values["vote_similarity.max_seeds"] != null) {
    $("vote-seeds").value = values["vote_similarity.max_seeds"];
  }
  // An hour past the fewest the edition's schedule holds may be no digest at all, and offers
  // that; any other hour the schedule does not hold says "Not set", as a select with no value does.
  const times = values["general.digest_schedule"] || [];
  HOURS.forEach((select, i) => {
    if (!neededHours().includes(select)) select.prepend(new Option(t("settings_option.schedule_none"), ""));
    if (times[i]) select.value = String(parseInt(times[i], 10));
    else if (neededHours().includes(select)) select.prepend(new Option(t("settings.not_set"), "", true, true));
    else select.value = "";
  });
  const cap = state.limits.max_articles_per_digest_max;
  if (cap != null) $("max-articles").max = String(cap);
  fillLanguages($("output-language"), state.languages, values["digest.output_language"]);
  fillTimezones($("timezone"), values["general.timezone"]);
  // A select would otherwise show its first option for a missing value. A missing
  // one shows its starting value, which a save stores; with no starting value it
  // says "Not set" and is not sent.
  for (const [id, key] of Object.entries(PLAIN)) {
    if (values[key] != null) $(id).value = values[key];
    else if ($(id).tagName !== "SELECT") continue;
    else if (key in state.starting) $(id).value = String(state.starting[key]);
    else $(id).prepend(new Option(t("settings.not_set"), "", true, true));
  }
  if (values["notify.discord_webhook_url"]) {
    $("discord-webhook").value = values["notify.discord_webhook_url"];
  }
  $("email-to").value = values["notify.email_to"] ?? "";
  $("email-from").value = values["notify.email_from"] ?? "";
  showNotifyState();
  markMissing();
  if (state.writable) {
    document.querySelectorAll("form.tab").forEach((form) => markClean(form));
    detectTimezone($("digest-form"));
  } else {
    SETTINGS_NOTICES.forEach((id) => {
      show("err", t("settings.no_settings_store"), id);
    });
  }
  updateDependencies();
  markPlanHours();
  markLocked();
}

// The hours the reader's plan holds: an hour past `limits.digest_times_max` is disabled, with the
// plan-limit line as a locked key's, and no save sends it. Of those, the first
// `limits.digest_times_min` need an hour; a later one left at no digest is not sent.
const planHours = () => HOURS.slice(0, state.limits.digest_times_max);
const neededHours = () => HOURS.slice(0, state.limits.digest_times_min);

function markPlanHours() {
  for (const select of HOURS.filter((hour) => !planHours().includes(hour))) {
    const line = document.createElement("p");
    line.className = "small";
    line.id = `${select.id}-locked`;
    line.dataset.lock = "plan-limit";
    line.textContent = t("lock_reason.plan-limit");
    select.before(line);
    select.disabled = true;
    describe(select, line.id, true);
  }
}

// Each locked key's controls are disabled, with one line in the small role below the help saying
// why, which is each control's description, as a dependency's line is (ui-language.md §4 field).
// Keys of one field locked for one reason share its line.
function markLocked() {
  for (const [key, {reason}] of Object.entries(state.locked)) {
    const controls = FIELDS[key].controls.map($);
    const field = controls[0].closest(".form > .field");
    let line = field.querySelector(`[data-lock="${reason}"]`);
    if (!line) {
      line = document.createElement("p");
      line.className = "small";
      line.id = `${controls[0].id}-locked`;
      line.dataset.lock = reason;
      line.textContent = t(`lock_reason.${reason}`);
      field.insertBefore(line, [...field.children].find((child) => child.contains(controls[0])));
    }
    for (const control of controls) {
      // A radio group's control is its container: each of its choices is disabled.
      const inputs = control.matches("input, select, textarea") ? [control] : control.querySelectorAll("input");
      inputs.forEach((input) => {
        input.disabled = true;
        describe(input, line.id, true);
      });
    }
  }
}

function chosen() {
  const el = document.querySelector('input[name=provider]:checked');
  return el && state.providers.find((p) => p.name === el.value);
}

function updateHint() {
  const p = chosen();
  // None calls no model, so there is no model to name.
  const none = p && p.name === "none";
  $("model-input").disabled = !!none || isLocked("llm_provider.model");
  if (none) $("model-input").value = "";
  $("model-input").dataset.placeholder = p && !none
    ? t("settings_option.model_default", {model: p.default_model}) : "";
  applyPlaceholder($("model-input"));
  // A locked choice makes no call, so it promises none; its lock line says why.
  const locked = isLocked("llm_provider.provider") || isLocked("llm_provider.model");
  $("model-hint").hidden = locked;
  $("model-hint").textContent = locked ? "" : !p ? t("settings.model_hint_pick")
    : none ? t("settings.model_hint_none")
    : t("settings.model_hint_call");
}

function updateEmbeddingHint() {
  const el = document.querySelector("input[name=embedding-provider]:checked");
  const p = el && state.embedding_providers.find((x) => x.name === el.value);
  $("embedding-model-input").dataset.placeholder = p
    ? t("settings_option.model_default", {model: p.default_model}) : "";
  applyPlaceholder($("embedding-model-input"));
}

// A setting that does nothing until another holds a value is disabled until then,
// with a line saying what it waits for (ui-language.md §4 field). Clef's option
// waits for two things: vote similarity, whose nearest votes it reads, as the Vote
// similarity select stands, unsaved or not; and its token, which only the server's
// environment can change. A locked select says only why it is locked.
function updateDependencies() {
  const votes = $("vote-enabled").value === "true";
  const source = $("preference-source");
  const open = !isLocked("digest.preference_source");
  source.querySelector('option[value="clef"]').disabled = !votes || !state.clef_ready;
  $("clef-needs-votes").hidden = votes || !open;
  describe(source, "clef-needs-votes", !votes && open);
  $("clef-needs").hidden = !!state.clef_ready || !open;
  describe(source, "clef-needs", !state.clef_ready && open);
}

$("vote-enabled").addEventListener("change", () => { if (state) updateDependencies(); });

// A "busy" notice says what a save is doing while it is out; its result replaces it.
function show(kind, text, target) {
  const el = typeof target === "string" ? $(target) : target;
  el.className = kind === "err" ? "notice err" : "notice";
  if (kind === "busy") el.setAttribute("aria-busy", "true");
  else el.removeAttribute("aria-busy");
  el.textContent = text;
  el.hidden = false;
}

// The notice below a field, shared by the controls of one row.
function fieldNotice(control) {
  const anchor = control.closest(".field-row") || control;
  let notice = anchor.nextElementSibling;
  if (!notice || !notice.hasAttribute("data-field-error")) {
    notice = document.createElement("div");
    notice.setAttribute("data-field-error", "");
    anchor.after(notice);
  }
  return notice;
}

// A refusal pinned to one field is marked there too, until it is edited; a
// screen reader hears it as the field's description.
function refuse(controls, text) {
  const notice = fieldNotice(controls[0]);
  notice.id ||= `${controls[0].id}-error`;
  controls.forEach((el) => {
    el.classList.add("invalid");
    el.setAttribute("aria-invalid", "true");
    describe(el, notice.id, true);
  });
  show("err", text, notice);
}

function refuseSetting(err) {
  if (FIELDS[err.field]) refuse(FIELDS[err.field].controls.map($), err.message);
}

// aria-describedby names every line that describes a control: its refusal, and the
// reason it is disabled, which come and go apart.
function describe(el, id, on) {
  const ids = new Set((el.getAttribute("aria-describedby") || "").split(" ").filter(Boolean));
  if (on) ids.add(id);
  else ids.delete(id);
  if (ids.size) el.setAttribute("aria-describedby", [...ids].join(" "));
  else el.removeAttribute("aria-describedby");
}

// A setting still missing keeps the aria-invalid its missing mark gives it.
function clearRefusal(el) {
  el.classList.remove("invalid");
  for (const id of (el.getAttribute("aria-describedby") || "").split(" ")) {
    if (document.getElementById(id)?.hasAttribute("data-field-error")) describe(el, id, false);
  }
  if (!isMissing(el)) el.removeAttribute("aria-invalid");
}

function unrefuse(scope) {
  scope.querySelectorAll(".invalid").forEach(clearRefusal);
  scope.querySelectorAll("[data-field-error]").forEach((notice) => { notice.hidden = true; });
}

function unrefuseEdited(control) {
  const marked = control.closest(".invalid");
  if (!marked) return;
  clearRefusal(marked);
  const anchor = marked.closest(".field-row") || marked;
  if (!anchor.querySelector(".invalid")) fieldNotice(marked).hidden = true;
}

// One Save, two routes: the LLM part is checked against its provider, the vote
// part against its embedder when it is on. Only a changed part is sent; a part
// that saved becomes clean, one that failed stays dirty.
$("model-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const form = $("model-form");
  const stored = {...clean.get(form)}, sent = snapshot(form);
  const keep = (part) => Object.keys(sent).filter(part).forEach((f) => { stored[f] = sent[f]; });
  const lines = [];
  let failed = false;
  saving.add(form);
  refresh(form);
  unrefuse(form);
  if (partChanged(form, LLM_PART)) {
    const p = chosen();
    show("busy", t("settings.checking_provider"), "model-result");
    try {
      if (!p) throw new Error(t("settings.pick_provider_first"));
      const data = await post("/api/settings", {provider: p.name, model: sent["model-input"].trim()});
      state.values["llm_provider.provider"] = data.provider;
      state.values["llm_provider.model"] = data.model;
      markSet(keysSavedBy("llm"));
      keep(LLM_PART);
      lines.push(`${data.detail}\n${data.note}`);
    } catch (err) {
      failed = true;
      refuseSetting(err);
      lines.push(err.message);
    }
  }
  if (Object.keys(sent).some((f) => VOTE_PART(f) && sent[f] !== stored[f])) {
    const embedder = document.querySelector("input[name=embedding-provider]:checked");
    const seeds = sent["vote-seeds"];
    const body = {
      enabled: {true: true, false: false}[sent["vote-enabled"]] ?? null,
      provider: embedder ? embedder.value : null,
      model: sent["embedding-model-input"].trim(),
      max_seeds: seeds === "" ? null : Number(seeds),
    };
    show("busy", body.enabled ? t("settings.checking_embedder") : t("settings.saving"), "model-result");
    try {
      const data = await post("/api/settings/vote-similarity", body);
      Object.assign(state.values, data.values);
      $("vote-enabled").querySelector('option[value=""]')?.remove();
      markSet(keysSavedBy("vote"));
      keep(VOTE_PART);
      lines.push(`${data.detail}\n${data.note}`);
    } catch (err) {
      failed = true;
      refuseSetting(err);
      lines.push(err.message);
    }
  }
  saving.delete(form);
  markClean(form, stored);
  show(failed ? "err" : "ok", lines.join("\n"), "model-result");
});

// A refusal of the request itself, before any setting is read: shown as it stands.
const refusal = (text) => Object.assign(new Error(text), {refusal: true});
// Access answers a reader it does not admit with a redirect the page cannot follow
// (opaqueredirect). Reloading /settings then serves the sign-in again.
const SESSION_EXPIRED = refusal(t("settings.session_expired"));
// The app Worker answers 403 with no `ok` when Cloudflare Access has not been configured here.
const ACCESS_NOT_SET_UP = refusal(t("settings.access_not_set_up"));
// A server answers a write from no page of its own 403 with `reason` `cross_origin`.
const CROSS_ORIGIN = refusal(t("settings.cross_origin"));

// A 403 says why in its body: a write from another page, in this page's words; any other the
// server's own refusal, as it words it; Access's names no `ok`, and means it is not set up here.
async function refusalOf(res) {
  if (res.type === "opaqueredirect") return SESSION_EXPIRED;
  if (res.status !== 403) return null;
  const data = await res.clone().json().catch(() => ({}));
  if (data.reason === "cross_origin") return CROSS_ORIGIN;
  if (data.ok === false && typeof data.error === "string" && data.error) return refusal(data.error);
  return ACCESS_NOT_SET_UP;
}

async function parseAnswer(res) {
  const refused = await refusalOf(res);
  if (refused) throw refused;
  return res.json();
}

// Rejects with what the reader needs: the server's own explanation when it
// gives one, otherwise what happened and what to do next.
// A write names `same-origin`, as hosted_settings.js's do, so under the hosted Worker's
// `Referrer-Policy: no-referrer` it sends a Referer to this origin and nowhere else. The Origin
// a write needs is sent either way: a fetch is in `cors` mode, which no referrer policy nulls.
async function post(url, body, method = "POST") {
  let res;
  try {
    res = await fetch(url, {
      method,
      headers: {"Content-Type": "application/json"},
      body: body ? JSON.stringify(body) : undefined,
      redirect: "manual",
      referrerPolicy: "same-origin",
    });
  } catch (err) {
    throw new Error(t("settings.unreachable", {error: err.message}));
  }
  const refused = await refusalOf(res);
  if (refused) throw refused;
  const data = await res.json().catch(() => ({}));
  if (data.ok) return data;
  const err = new Error(data.error || t("settings.answered_without_reason", {status: String(res.status)}));
  // The setting or source field the refusal is about, for the page to mark.
  err.field = data.field;
  err.status = res.status;
  err.body = data;
  throw err;
}

const plainValue = (input) => {
  if (input.type === "number") return input.value === "" ? null : Number(input.value);
  // The type size is stored as a number, which a select only holds as text.
  if (input.id === "type-scale") return input.value === "" ? null : Number(input.value);
  // A switch is stored as a boolean; its select holds "true" or "false".
  if (input.id === "rank-by-preference" || input.id === "summarize-follow") {
    return {true: true, false: false}[input.value] ?? null;
  }
  // The style prompt is the reader's own words, spaces included.
  return input.id === "style-prompt" ? input.value : input.value.trim();
};

const shownValue = (value) => {
  if (value === "") return t("settings.value_empty");
  const text = String(value);
  return text.length > 40 ? `${text.slice(0, 40)}…` : text;
};

// Every changed plain field of `form`, and every one it can save as it stands, in
// one request, all or nothing. A field
// that saved takes its sent value in `stored`; the result is one notice line.
async function savePlain(form, stored) {
  const ids = Object.keys(PLAIN).filter((id) => form.contains($(id))
    && ($(id).value !== stored[id] || unsavedIn(form).includes(PLAIN[id])));
  if (!ids.length) return null;
  const sent = Object.fromEntries(ids.map((id) => [id, $(id).value]));
  const values = Object.fromEntries(ids.map((id) => [PLAIN[id], plainValue($(id))]));
  try {
    const data = await post("/api/settings/values", {values});
    Object.assign(stored, sent);
    Object.assign(state.values, data.values);
    markSet(Object.keys(data.values));
    ids.forEach((id) => $(id).querySelector('option[value=""]')?.remove());
    // The Worker sizes the next page it serves; this one follows at once.
    const scale = data.values["digest.type_scale"];
    if (scale != null) document.documentElement.style.setProperty("--type-scale", String(scale));
    const parts = ids.map((id) => t("settings.saved_value",
      {label: FIELDS[PLAIN[id]].label, value: shownValue(data.values[PLAIN[id]])}));
    return {ok: true, line: t("settings.saved_values", {values: list(parts), note: data.note})};
  } catch (err) {
    refuseSetting(err);
    const labels = ids.map((id) => FIELDS[PLAIN[id]].label);
    return {ok: false, line: t("settings.not_saved", {labels: list(labels), error: err.message || String(err)})};
  }
}

const HOURS = [$("morning"), $("evening")];

// An empty hour the schedule needs is refused here: padded, it would reach the server as 00:00.
// Returns the reason shown beside the hours, or null when each it needs is filled.
function emptyHours() {
  const empty = neededHours().filter((input) => input.value === "");
  if (!empty.length) return null;
  const names = listJoin(empty.map((input) => input.labels[0].textContent));
  const reason = t("settings.hours_need", {names, count: empty.length});
  refuse(empty, reason);
  return reason;
}

// One Save, two endpoints: only a changed part is sent, the hours first, and
// both are tried. A part that saved becomes clean; one that failed stays dirty.
$("digest-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const form = $("digest-form");
  const [morning, evening] = HOURS.map((input) => input.value);
  const stored = {...clean.get(form)};
  const lines = [];
  let failed = false;
  saving.add(form);
  refresh(form);
  unrefuse(form);
  show("busy", t("settings.saving"), "digest-result");
  const hoursChanged = morning !== stored.morning || evening !== stored.evening;
  const empty = hoursChanged && emptyHours();
  if (empty) {
    failed = true;
    lines.push(t("settings.hours_not_saved", {error: empty}));
  } else if (hoursChanged) {
    const times = planHours().filter((hour) => hour.value !== "")
      .map((hour) => `${hour.value.padStart(2, "0")}:00`);
    try {
      const data = await post("/api/settings/schedule", {times});
      const [savedMorning, savedEvening] = data.times;
      lines.push(savedEvening === undefined
        ? t("settings.hour_saved", {morning: savedMorning, note: data.note})
        : t("settings.hours_saved", {morning: savedMorning, evening: savedEvening, note: data.note}));
      neededHours().forEach((hour) => hour.querySelector('option[value=""]')?.remove());
      Object.assign(stored, {morning, evening});
      markSet(keysSavedBy("schedule"));
    } catch (err) {
      failed = true;
      refuseSetting(err);
      lines.push(t("settings.hours_not_saved", {error: err.message || String(err)}));
    }
  }
  const plain = await savePlain(form, stored);
  if (plain) {
    failed = failed || !plain.ok;
    lines.push(plain.line);
  }
  saving.delete(form);
  markClean(form, stored);
  show(failed ? "err" : "ok", lines.join("\n"), "digest-result");
});

$("pipeline-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const form = $("pipeline-form");
  const stored = {...clean.get(form)};
  saving.add(form);
  refresh(form);
  unrefuse(form);
  show("busy", t("settings.saving"), "pipeline-result");
  const plain = await savePlain(form, stored);
  saving.delete(form);
  markClean(form, stored);
  if (plain) show(plain.ok ? "ok" : "err", plain.line, "pipeline-result");
});

// The Notifications form saves in two parts too: the webhook and the mail addresses.
const DISCORD_PART = (field) => field === "discord-webhook";
const EMAIL_PART = (field) => !DISCORD_PART(field);

$("notify-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const form = $("notify-form"), field = $("discord-webhook");
  const stored = {...clean.get(form)}, sent = snapshot(form);
  const changed = (part) => Object.keys(sent).some((f) => part(f) && sent[f] !== stored[f]);
  const keep = (part) => Object.keys(sent).filter(part).forEach((f) => { stored[f] = sent[f]; });
  const lines = [];
  let failed = false;
  saving.add(form);
  refresh(form);
  unrefuse(form);
  if (changed(DISCORD_PART)) {
    const url = sent["discord-webhook"];
    show("busy", t("settings.checking_discord"), "notify-result");
    try {
      const data = await post("/api/settings/notify", {discord_webhook_url: url});
      state.values["notify.discord_webhook_url"] = data.discord_webhook_url;
      // The stored value comes back masked; an edit typed meanwhile is kept.
      if (field.value === url) field.value = data.discord_webhook_url;
      markSet(keysSavedBy("notify"));
      showNotifyState();
      stored["discord-webhook"] = data.discord_webhook_url;
      lines.push(`${data.detail} ${data.note}`);
    } catch (err) {
      failed = true;
      refuseSetting(err);
      lines.push(err.message);
    }
  }
  if (changed(EMAIL_PART) || unsavedIn(form).length) {
    show("busy", t("settings.sending_test"), "notify-result");
    try {
      const data = await post("/api/settings/email",
        {email_to: sent["email-to"], email_from: sent["email-from"]});
      state.values["notify.email_to"] = data["notify.email_to"];
      state.values["notify.email_from"] = data["notify.email_from"];
      markSet(keysSavedBy("email"));
      keep(EMAIL_PART);
      lines.push(data.detail ? `${data.detail} ${data.note}` : data.note);
    } catch (err) {
      failed = true;
      refuseSetting(err);
      lines.push(err.message);
    }
  }
  saving.delete(form);
  markClean(form, stored);
  show(failed ? "err" : "ok", lines.join("\n"), "notify-result");
});

// "" is off by choice; a missing webhook is neither on nor off yet.
function showNotifyState() {
  const webhook = state.values["notify.discord_webhook_url"];
  $("notify-state").hidden = webhook !== "";
  $("notify-off").hidden = !(webhook !== "" && state.writable && !isLocked("notify.discord_webhook_url"));
}

// The spec's destructive confirm, as Retire does it: the stored URL cannot be
// read back, so turning it off is not undone by pressing Save again.
let notifyOffTimer;
const disarmNotifyOff = () => {
  clearTimeout(notifyOffTimer);
  $("notify-off").classList.remove("armed");
  $("notify-off").textContent = t("settings.turn_off");
};

$("notify-off").addEventListener("click", async () => {
  const button = $("notify-off"), form = $("notify-form");
  if (!button.classList.contains("armed")) {
    button.classList.add("armed");
    button.textContent = t("settings.confirm_turn_off");
    notifyOffTimer = setTimeout(disarmNotifyOff, 3000);
    return;
  }
  disarmNotifyOff();
  button.disabled = true;
  show("busy", t("settings.turning_off"), "notify-result");
  try {
    const data = await post("/api/settings/notify", {off: true});
    state.values["notify.discord_webhook_url"] = data.discord_webhook_url;
    $("discord-webhook").value = data.discord_webhook_url;
    markSet(keysSavedBy("notify"));
    showNotifyState();
    // Only the webhook is saved; unsaved mail edits stay dirty.
    markClean(form, {...clean.get(form), "discord-webhook": data.discord_webhook_url});
    show("ok", data.note, "notify-result");
  } catch (err) {
    show("err", err.message, "notify-result");
  } finally {
    button.disabled = false;
  }
});

let sources = [];
let sourcesWritable = false;
let filter = "all";
// Which editor is open: null for none, "" for a new source, else its name.
let openName = null;

const EMPTY = {
  all: t("settings.no_sources"),
  rss: t("settings.no_rss_sources"),
  newsletter: t("settings.no_newsletter_sources"),
};

const NO_SOURCE_TABLE = t("settings.no_source_table");

const rowOf = (name) => document.querySelector(`tr.src-row[data-name="${CSS.escape(name)}"]`);

const sourcesNav = () => document.querySelector('.settings-nav a[data-tab="sources"]');

// Only what `cyris doctor` would warn about: a feed failing now and then shows nothing.
const feedProblem = (s) => s.health?.problems?.length
  ? `<span class="small feed-problem">${esc(s.health.problems.join(" · "))}</span>`
  : "";

function renderSources() {
  const rows = sources.filter((s) => filter === "all" || s.type === filter);
  $("src-body").innerHTML = rows.length
    ? rows.map((s) => `
      <tr class="src-row" data-name="${esc(s.name)}" tabindex="0">
        <td class="name">${esc(s.name)}${feedProblem(s)}</td>
        <td><span class="label">${esc(t(`source_type.${s.type}`))}</span></td>
        <td><span class="pill">${esc(t(`lane.${s.lane}`))}</span></td>
        <td class="target">${esc(s.url || s.email_match || "—")}</td>
        <td class="small">${esc((s.tags || []).join(", ") || "—")}</td>
      </tr>`).join("")
    : `<tr><td colspan="5" class="small">${esc(EMPTY[sources.length ? filter : "all"])}</td></tr>`;
  sourcesNav().classList.remove("dirty");
  if (openName !== null) openEditor(openName);
}

function editorValues(ed) {
  return JSON.stringify([...ed.querySelectorAll("input, select")].map((i) => i.value)
    .concat(ed.querySelector('[data-type][aria-pressed="true"]').dataset.type));
}

function openEditor(name) {
  const adding = name === "";
  const s = adding
    ? {name: "", type: "rss", lane: "skim", tags: []}
    : sources.find((x) => x.name === name);
  const anchor = adding ? null : rowOf(name);
  if (!adding && !(s && anchor)) {
    openName = null;
    return null;
  }
  const ed = $("editor-tpl").content.firstElementChild.cloneNode(true);
  const q = (selector) => ed.querySelector(selector);
  if (anchor) {
    anchor.after(ed);
    anchor.classList.add("open");
  } else {
    $("src-body").prepend(ed);
  }
  q(".editor-title").textContent = adding ? t("settings.new_source") : t("settings.editing", {name: s.name});
  q("#e-name").value = s.name;
  q("#e-name").readOnly = !adding;
  q("#e-lane").value = s.lane;
  q("#e-url").value = s.url || "";
  q("#e-email").value = s.email_match || "";
  q("#e-home").value = s.homepage || "";
  q("#e-tags").value = (s.tags || []).join(", ");
  const save = q('[data-act="save"]'), retire = q('[data-act="retire"]');
  const setType = (type) => {
    ed.querySelectorAll("[data-type]").forEach((b) => {
      b.setAttribute("aria-pressed", String(b.dataset.type === type));
    });
    ed.querySelectorAll("[data-for]").forEach((field) => {
      field.hidden = field.dataset.for !== type;
    });
  };
  setType(s.type);
  const initial = editorValues(ed);
  const refreshEditor = () => {
    const dirty = editorValues(ed) !== initial;
    save.disabled = ed.inert || !sourcesWritable || !dirty || !q("#e-name").value.trim();
    sourcesNav().classList.toggle("dirty", dirty && sourcesWritable);
  };
  ed.querySelectorAll("[data-type]").forEach((b) => {
    b.addEventListener("click", () => { setType(b.dataset.type); refreshEditor(); });
  });
  const editorEdited = () => {
    if (sourcesWritable) ed.querySelectorAll(".notice").forEach((n) => { n.hidden = true; });
    ed.querySelectorAll(".invalid").forEach(clearRefusal);
    refreshEditor();
  };
  ed.addEventListener("input", editorEdited);
  ed.addEventListener("change", editorEdited);
  refreshEditor();
  retire.hidden = adding;
  if (!sourcesWritable) {
    // Rows still open so their values stay readable; nothing in them writes.
    retire.disabled = true;
    show("err", NO_SOURCE_TABLE, save.parentElement.querySelector(".notice"));
  }
  q('[data-act="cancel"]').addEventListener("click", () => {
    openName = null;
    renderSources();
    (adding ? $("add-source") : rowOf(name)).focus();
  });
  save.addEventListener("click", () => saveSource(ed, save));
  // The spec's destructive confirm: the first press arms the button in place,
  // and only a second press within three seconds retires.
  let armTimer;
  const disarm = () => {
    clearTimeout(armTimer);
    retire.classList.remove("armed");
    retire.textContent = t("settings.retire");
  };
  retire.addEventListener("click", async () => {
    if (!retire.classList.contains("armed")) {
      retire.classList.add("armed");
      retire.textContent = t("settings.confirm_retire");
      armTimer = setTimeout(disarm, 3000);
      return;
    }
    disarm();
    const data = await writeSource(`/api/sources/${encodeURIComponent(s.name)}`, "DELETE", null,
                                   retire, t("settings.retiring"));
    if (!data) {
      returnFocus(retire);
      return;
    }
    openName = null;
    await loadSources();
    show("ok", t("settings.source_retired", {name: s.name, note: data.note}), "sources-notice");
    returnFocus($("add-source"));
  });
  q("#e-name").focus();
  return ed;
}

function loaded(d) {
  sources = d.sources;
  sourcesWritable = d.writable;
  $("add-source").disabled = !d.writable;
  // A deployment that caps its sources (the hosted one) says how many are used; one with no cap
  // answers null and shows nothing.
  const cap = $("sources-cap");
  cap.hidden = d.max_sources == null;
  if (d.max_sources != null) cap.textContent = t("settings.sources_used", {count: sources.length, max: d.max_sources});
  if (!d.writable) show("err", NO_SOURCE_TABLE, "sources-notice");
  // No source publishes no issue, so the category is marked like a missing
  // setting; unlike one, the next run waits instead of stopping.
  sourcesNav().classList.toggle("missing", !sources.length);
  renderSources();
}

function pressFilter(value) {
  filter = value;
  document.querySelectorAll("[data-filter]").forEach((b) => {
    b.setAttribute("aria-pressed", String(b.dataset.filter === value));
  });
}

document.querySelectorAll("[data-filter]").forEach((button) => {
  button.addEventListener("click", () => {
    pressFilter(button.dataset.filter);
    openName = null;
    renderSources();
  });
});

$("src-body").addEventListener("click", (e) => {
  const row = e.target.closest("tr.src-row");
  if (!row) return;
  const name = row.dataset.name;
  openName = openName === name ? null : name;
  renderSources();
  if (openName === null) rowOf(name).focus();
});

$("add-source").addEventListener("click", () => {
  openName = "";
  renderSources();
});

$("src-body").addEventListener("keydown", (e) => {
  if ((e.key === "Enter" || e.key === " ") && e.target.matches("tr.src-row")) {
    // Space would otherwise scroll the page.
    e.preventDefault();
    e.target.click();
  }
});

// Disabling the focused button, or locking the editor around it, drops focus to
// the body; give it back, unless the reader has moved on meanwhile.
function returnFocus(control) {
  if (!document.activeElement || document.activeElement === document.body) control.focus();
}

// Resolves to the response on success, or null once the failure is shown
// beside the pressed button.
async function writeSource(url, method, body, button, doing) {
  const notice = button.parentElement.querySelector(".notice");
  button.disabled = true;
  show("busy", doing, notice);
  try {
    return await post(url, body, method);
  } catch (err) {
    show("err", err.message, notice);
    const control = err.field && button.closest("tr.editor").querySelector(`[name="${err.field}"]`);
    if (control) refuse([control], err.message);
  }
  button.disabled = false;
  return null;
}

async function saveSource(ed, button) {
  const q = (selector) => ed.querySelector(selector);
  const name = q("#e-name").value.trim();
  const type = q('[data-type][aria-pressed="true"]').dataset.type;
  // Only the fields this type shows: a stale URL on a newsletter, or a sender
  // on a feed, would be stored with nothing on the page to reveal it.
  const shown = (selector) =>
    q(selector).closest("[data-for]").dataset.for === type ? q(selector).value.trim() || null : null;
  // Locked while the save is out: a success rebuilds the editor from what was
  // stored, which would drop anything typed meanwhile.
  ed.inert = true;
  const data = await writeSource("/api/sources", "POST", {
    name,
    type,
    lane: q("#e-lane").value,
    url: shown("#e-url"),
    email_match: shown("#e-email"),
    homepage: shown("#e-home"),
    tags: q("#e-tags").value.split(",").map((tag) => tag.trim()).filter(Boolean),
  }, button, t("settings.saving"));
  if (!data) {
    ed.inert = false;
    returnFocus(button);
    return;
  }
  // A source saved out of the active filter would lose its row, and the result
  // beside its Save with it.
  if (filter !== "all" && filter !== type) pressFilter("all");
  openName = data.name;
  await loadSources();
  const reopened = document.querySelector("tr.editor");
  show("ok", t("settings.item_saved", {name: data.name, note: data.note}),
       reopened ? reopened.querySelector(".notice") : "sources-notice");
}

const loadSources = () =>
  fetch("/api/sources", {redirect: "manual"})
    .then(parseAnswer)
    .then(loaded)
    .catch((e) => {
      $("src-body").querySelector("[data-loading]")?.remove();
      $("add-source").disabled = true;
      show("err", e.refusal ? e.message
        : t("settings.load_sources_failed", {error: String(e)}), "sources-notice");
    });

loadSources();

// Tracked topics: the same table and in-place editor as sources. An empty list
// is a valid answer, so Tracking never takes the missing dot.
let topics = [];
let topicsWritable = false;
// The model the next run embeds with: a new topic starts from it, and a topic
// set for another one is marked, because the run skips it.
let topicModel = "";
// Which editor is open: null for none, "" for a new topic, else its name.
let openTopic = null;

const NO_TOPIC_TABLE = t("settings.no_topic_table");

const topicRow = (name) => $("topic-body").querySelector(`tr.src-row[data-name="${CSS.escape(name)}"]`);

const trackingNav = () => document.querySelector('.settings-nav a[data-tab="tracking"]');

const topicProblem = (topic) => topicModel && topic.model !== topicModel
  ? `<span class="small feed-problem">${
    esc(t("settings.topic_other_model", {model: topic.model, current: topicModel}))}</span>`
  : "";

function renderTopics() {
  $("topic-body").innerHTML = topics.length
    ? topics.map((topic) => `
      <tr class="src-row" data-name="${esc(topic.name)}" tabindex="0">
        <td class="name">${esc(topic.name)}${topicProblem(topic)}</td>
        <td class="small">${esc(topic.description)}</td>
        <td class="target">${esc(topic.threshold)}</td>
        <td class="target">${esc(topic.model)}</td>
      </tr>`).join("")
    : `<tr><td colspan="4" class="small">${esc(t("settings.no_topics"))}</td></tr>`;
  trackingNav().classList.remove("dirty");
  if (openTopic !== null) openTopicEditor(openTopic);
}

function openTopicEditor(name) {
  const adding = name === "";
  const topic = adding
    ? {name: "", description: "", threshold: "", model: topicModel}
    : topics.find((x) => x.name === name);
  const anchor = adding ? null : topicRow(name);
  if (!adding && !(topic && anchor)) {
    openTopic = null;
    return null;
  }
  const ed = $("topic-editor-tpl").content.firstElementChild.cloneNode(true);
  const q = (selector) => ed.querySelector(selector);
  if (anchor) {
    anchor.after(ed);
    anchor.classList.add("open");
  } else {
    $("topic-body").prepend(ed);
  }
  q(".editor-title").textContent = adding ? t("settings.new_topic") : t("settings.editing", {name: topic.name});
  q("#t-name").value = topic.name;
  q("#t-name").readOnly = !adding;
  q("#t-description").value = topic.description;
  q("#t-threshold").value = topic.threshold;
  q("#t-model").value = topic.model;
  const save = q('[data-act="save"]'), remove = q('[data-act="remove"]');
  const values = () => JSON.stringify([...ed.querySelectorAll("input, textarea")].map((i) => i.value));
  const initial = values();
  const refreshEditor = () => {
    const dirty = values() !== initial;
    save.disabled = ed.inert || !topicsWritable || !dirty || !q("#t-name").value.trim();
    trackingNav().classList.toggle("dirty", dirty && topicsWritable);
  };
  const editorEdited = () => {
    if (topicsWritable) ed.querySelectorAll(".notice").forEach((n) => { n.hidden = true; });
    ed.querySelectorAll(".invalid").forEach(clearRefusal);
    refreshEditor();
  };
  ed.addEventListener("input", editorEdited);
  ed.addEventListener("change", editorEdited);
  refreshEditor();
  remove.hidden = adding;
  if (!topicsWritable) {
    remove.disabled = true;
    show("err", NO_TOPIC_TABLE, save.parentElement.querySelector(".notice"));
  }
  q('[data-act="cancel"]').addEventListener("click", () => {
    openTopic = null;
    renderTopics();
    (adding ? $("add-topic") : topicRow(name)).focus();
  });
  save.addEventListener("click", () => saveTopic(ed, save));
  // The spec's destructive confirm, as Retire does it.
  let armTimer;
  const disarm = () => {
    clearTimeout(armTimer);
    remove.classList.remove("armed");
    remove.textContent = t("settings.remove");
  };
  remove.addEventListener("click", async () => {
    if (!remove.classList.contains("armed")) {
      remove.classList.add("armed");
      remove.textContent = t("settings.confirm_remove");
      armTimer = setTimeout(disarm, 3000);
      return;
    }
    disarm();
    const data = await writeSource(`/api/topics/${encodeURIComponent(topic.name)}`, "DELETE", null,
                                   remove, t("settings.removing"));
    if (!data) {
      returnFocus(remove);
      return;
    }
    openTopic = null;
    await loadTopics();
    show("ok", t("settings.topic_removed", {name: topic.name, note: data.note}), "topics-notice");
    returnFocus($("add-topic"));
  });
  q("#t-name").focus();
  return ed;
}

async function saveTopic(ed, button) {
  const q = (selector) => ed.querySelector(selector);
  const threshold = q("#t-threshold").value;
  // Locked while the save is out, as a source editor is.
  ed.inert = true;
  const data = await writeSource("/api/topics", "POST", {
    name: q("#t-name").value.trim(),
    description: q("#t-description").value.trim(),
    // No number is not 0: the server refuses it rather than store a threshold nobody set.
    threshold: threshold === "" ? null : Number(threshold),
    model: q("#t-model").value.trim(),
  }, button, t("settings.saving"));
  if (!data) {
    ed.inert = false;
    returnFocus(button);
    return;
  }
  openTopic = data.name;
  await loadTopics();
  const reopened = $("topic-body").querySelector("tr.editor");
  show("ok", t("settings.item_saved", {name: data.name, note: data.note}),
       reopened ? reopened.querySelector(".notice") : "topics-notice");
}

$("topic-body").addEventListener("click", (e) => {
  const row = e.target.closest("tr.src-row");
  if (!row) return;
  const name = row.dataset.name;
  openTopic = openTopic === name ? null : name;
  renderTopics();
  if (openTopic === null) topicRow(name).focus();
});

$("topic-body").addEventListener("keydown", (e) => {
  if ((e.key === "Enter" || e.key === " ") && e.target.matches("tr.src-row")) {
    // Space would otherwise scroll the page.
    e.preventDefault();
    e.target.click();
  }
});

$("add-topic").addEventListener("click", () => {
  openTopic = "";
  renderTopics();
});

const loadTopics = () =>
  fetch("/api/topics", {redirect: "manual"})
    .then(parseAnswer)
    .then((d) => {
      topics = d.topics;
      topicsWritable = d.writable;
      topicModel = d.embedding_model;
      $("add-topic").disabled = !d.writable;
      if (!d.writable) show("err", NO_TOPIC_TABLE, "topics-notice");
      renderTopics();
    })
    .catch((e) => {
      $("topic-body").querySelector("[data-loading]")?.remove();
      $("add-topic").disabled = true;
      show("err", e.refusal ? e.message
        : t("settings.load_topics_failed", {error: String(e)}), "topics-notice");
    });

loadTopics();

fetch("/api/settings", {redirect: "manual"})
  .then(parseAnswer)
  .then((d) => { state = d; render(); })
  .catch((e) => {
    // Every Save stays disabled: tracking only starts once the values are known.
    const text = e.refusal ? e.message
      : t("settings.load_settings_failed", {error: String(e)});
    SETTINGS_NOTICES.forEach((id) => show("err", text, id));
  })
  .finally(() => document.querySelectorAll("form.tab [data-loading]").forEach((el) => el.remove()));

/static/style.css.body:
/* The rules every reader-facing surface shares, for the page served from
   here (/settings). A copy of `_tokens.css.j2` and `_components.css.j2` in
   `adapters/output/templates/`: a digest is a standalone HTML file deployed to
   Pages, so it cannot link this stylesheet and carries the partials instead.
   `tests/test_digest_css_partials.py` enforces that the two agree. */
:root {
    --bg: #07070a;
    --bg-elev: #0d0d12;
    --surface: #11111a;
    --surface-2: #161622;
    --border: #1f1f2e;
    --border-strong: #2a2a40;
    --text: #ebebf2;
    --text-dim: #8a8aa0;
    --text-faint: #62627a;
    --accent: #c6ff3d;
    --accent-dim: #8aa829;
    --warn: #ff5b8a;
    --accent-tint: rgba(198, 255, 61, 0.07);
    --warn-tint: rgba(255, 91, 138, 0.12);
    --grid: rgba(198, 255, 61, 0.035);
    --s-1: 4px; --s-2: 8px; --s-3: 12px; --s-4: 16px; --s-5: 20px;
    --s-6: 24px; --s-8: 32px; --s-12: 48px; --s-16: 64px; --s-20: 80px;
    --font-sans: 'Geist', system-ui, -apple-system, sans-serif;
    --font-mono: 'Geist Mono', ui-monospace, monospace;
    --type-scale: 1;
    --r-control: 6px;
    --r-tag: 999px;
    --t-fast: 150ms ease-out;
    --t-opening-overload: 3.6s;
    --t-opening-calm: 2.9s;
    --bar-h: 60px;
    --measure: 640px;
    --measure-wide: 760px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

@keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: .5; }
}

.btn { display: inline-flex; align-items: center; gap: var(--s-2); height: 44px; padding: 0 var(--s-5); border: 1px solid transparent; border-radius: var(--r-control); font-family: var(--font-mono); font-size: calc(12px * var(--type-scale)); font-weight: 500; letter-spacing: .1em; text-transform: uppercase; text-decoration: none; cursor: pointer; transition: color var(--t-fast), background-color var(--t-fast), border-color var(--t-fast), opacity var(--t-fast); }
.btn.sm { height: 34px; padding: 0 var(--s-2); letter-spacing: .06em; }
.btn.primary { background: var(--accent); color: var(--bg); }
.btn.primary:where(:not(:disabled)):hover { background: #d4ff66; }
.btn.secondary { background: var(--surface-2); border-color: var(--border-strong); color: var(--text-dim); }
.btn.secondary:where(:not(:disabled)):hover { color: var(--text); }
.btn.danger { background: transparent; border-color: var(--warn); color: var(--warn); }
.btn.danger:where(:not(:disabled)):hover, .btn.danger.armed { background: var(--warn-tint); }
.btn:where(:not(:disabled)):active { opacity: .7; }
.btn:disabled { cursor: default; opacity: .4; }
.input, .select { width: 100%; height: 48px; padding: 0 var(--s-4); border: 1px solid var(--border-strong); border-radius: var(--r-control); background: var(--bg-elev); color: var(--text); font-size: calc(16px * var(--type-scale)); transition: border-color var(--t-fast); }
.input.invalid { border-color: var(--warn); }
.select.invalid { border-color: var(--warn); }
.input[aria-invalid="true"] { border-color: var(--warn); }
.select[aria-invalid="true"] { border-color: var(--warn); }
.input:focus, .select:focus { border-color: var(--accent); outline: none; }
.input:disabled, .select:disabled { cursor: default; opacity: .4; }
textarea.input { height: auto; padding-block: var(--s-3); line-height: 1.5; resize: vertical; }
.field { display: grid; gap: var(--s-2); }
details.more summary { cursor: pointer; font-family: var(--font-mono); font-size: calc(12px * var(--type-scale)); letter-spacing: .1em; text-transform: uppercase; color: var(--text-dim); list-style: none; }
details.more summary::before { content: "+ "; }
details.more[open] summary::before { content: "− "; }
details.more p { margin-top: var(--s-2); }
/* The choice list (ui-language.md §4) clips none of its rows, like the checklist: a rounded
   clip would take the first and last rows' corners from their taps (§4 tap area). */
.choices { display: grid; border: 1px solid var(--border); border-radius: var(--r-control); background: var(--bg-elev); }
.choices.invalid { border-color: var(--warn); }
.choice { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--s-1) var(--s-3); align-items: center; padding: var(--s-3) var(--s-4); border-bottom: 1px solid var(--border); cursor: pointer; transition: background-color var(--t-fast); }
.choice:last-child { border-bottom: 0; }
.choice:hover { background: var(--surface); }
.choice input { accent-color: var(--accent); }
.choice.unavailable { cursor: not-allowed; }
.choice.unavailable input, .choice.unavailable .name { opacity: .5; }
.choice.unavailable:hover { background: transparent; }
/* The checklist (ui-language.md §4): a fieldset with no browser border or padding. */
.sources-check { min-width: 0; margin: 0 0 var(--s-3); padding: 0; border: 1px solid var(--border); border-radius: var(--r-control); background: var(--bg-elev); }
.sources-check > .label { padding: var(--s-2) var(--s-4) 0; }
.sources-check .choice { justify-content: flex-start; }
.choice .name { flex: 1 1 auto; font-weight: 600; font-size: calc(18px * var(--type-scale)); }
/* The toggle tile (ui-language.md §4): a button per option, pressed or not, with a mark that is not colour alone. */
.tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 160px), 1fr)); gap: var(--s-2); }
.tile { position: relative; display: grid; align-content: start; gap: var(--s-1); min-height: var(--s-16); padding: var(--s-3) var(--s-8) var(--s-3) var(--s-4); border: 1px solid var(--border-strong); border-radius: var(--r-control); background: var(--bg-elev); color: var(--text); font-family: var(--font-sans); text-align: left; cursor: pointer; transition: background-color var(--t-fast), border-color var(--t-fast), opacity var(--t-fast); }
.tile:hover { background: var(--surface); }
.tile:active { opacity: .7; }
.tile::after { content: ""; position: absolute; top: var(--s-3); right: var(--s-3); width: var(--s-3); height: var(--s-3); border: 1px solid var(--border-strong); transition: background-color var(--t-fast), border-color var(--t-fast); }
.tile[aria-pressed="true"] { border-color: var(--accent); background: var(--accent-tint); }
.tile[aria-pressed="true"]::after { border-color: var(--accent); background: var(--accent); }
.tile[aria-pressed="true"] .label { color: var(--accent); }
.tile .name { font-weight: 600; font-size: calc(18px * var(--type-scale)); line-height: 1.3; }
.seg { display: inline-flex; overflow: hidden; border: 1px solid var(--border-strong); border-radius: var(--r-control); }
.seg > * { display: inline-flex; align-items: center; height: 44px; padding: 0 var(--s-4); border: 0; border-bottom: 2px solid transparent; background: transparent; color: var(--text-dim); font-family: var(--font-mono); font-size: calc(12px * var(--type-scale)); font-weight: 500; letter-spacing: .1em; text-transform: uppercase; text-decoration: none; cursor: pointer; transition: color var(--t-fast), background-color var(--t-fast), border-color var(--t-fast); }
.seg > * + * { border-left: 1px solid var(--border-strong); }
.seg > *:hover { color: var(--text); }
.seg > [aria-current="page"], .seg > [aria-pressed="true"] { background: var(--surface-2); border-bottom-color: var(--accent); color: var(--accent); }
.panel { background: var(--bg-elev); border: 1px solid var(--border); }
.panel + .panel { margin-top: var(--s-5); }
.panel-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s-4); padding: var(--s-3) var(--s-5); background: var(--surface); border-bottom: 1px solid var(--border); }
.list-row { display: grid; align-items: center; gap: var(--s-4); padding: var(--s-3) var(--s-5); border-bottom: 1px solid var(--border); transition: background-color var(--t-fast); }
.list-row:last-child { border-bottom: 0; }
.list-row:hover { background: var(--surface); }
.pill { padding: 2px 10px; border: 1px solid var(--border-strong); border-radius: var(--r-tag); background: var(--surface-2); color: var(--text-dim); font-family: var(--font-mono); font-size: calc(12px * var(--type-scale)); letter-spacing: .04em; white-space: nowrap; }
.pill.score { color: var(--accent); border-color: var(--accent-dim); background: var(--accent-tint); }
.state { font-family: var(--font-mono); font-size: calc(11px * var(--type-scale)); letter-spacing: .1em; text-transform: uppercase; }
.state.accepted { color: var(--accent); }
.state.pending { color: var(--text-dim); }
.state.rejected { color: var(--text-dim); }
.notice { padding: var(--s-2) var(--s-3); border-left: 2px solid var(--accent); background: var(--accent-tint); font-size: calc(14px * var(--type-scale)); line-height: 1.5; white-space: pre-wrap; }
.notice.err { border-left-color: var(--warn); background: var(--warn-tint); }
.label { font-family: var(--font-mono); font-weight: 500; font-size: calc(12px * var(--type-scale)); text-transform: uppercase; letter-spacing: .1em; color: var(--text-dim); }
.data { font-family: var(--font-mono); font-size: calc(14px * var(--type-scale)); font-variant-numeric: tabular-nums; }
.display { font-family: var(--font-sans); font-weight: 500; font-size: calc(clamp(46px, 7vw, 84px) * var(--type-scale)); line-height: 1; letter-spacing: -.02em; text-wrap: balance; }
.display em { font-style: normal; color: var(--accent); }
.heading { font-weight: 600; font-size: calc(24px * var(--type-scale)); letter-spacing: -.015em; line-height: 1.3; }
.small { font-size: calc(14px * var(--type-scale)); line-height: 1.5; color: var(--text-dim); }
.site-bar { position: sticky; top: 0; z-index: 10; height: var(--bar-h); background: rgba(7, 7, 10, .88); border-bottom: 1px solid var(--border); }
.site-bar-inner { height: 100%; max-width: 1240px; margin: 0 auto; padding: 0 var(--s-4); display: flex; align-items: center; justify-content: space-between; gap: var(--s-4); }
.brand { display: flex; align-items: center; gap: var(--s-3); text-decoration: none; }
.brand-mark { width: 12px; height: 12px; background: var(--accent); box-shadow: 0 0 12px rgba(198,255,61,.45); animation: pulse 2.4s ease-in-out infinite; }
.brand-name { font-family: var(--font-mono); font-size: calc(14px * var(--type-scale)); letter-spacing: .18em; font-weight: 600; }
.site-nav { display: flex; gap: var(--s-5); }
.site-nav a { text-decoration: none; padding: var(--s-1) 0; border-bottom: 1px solid transparent; transition: color var(--t-fast), border-color var(--t-fast); }
.site-nav a:hover { color: var(--text); }
.site-nav a[aria-current="page"] { color: var(--text); border-bottom-color: var(--accent); }
.page-head { display: grid; gap: var(--s-4); margin-bottom: var(--s-12); }
.issue-bar { border-bottom: 1px solid var(--border); background: var(--bg-elev); }
.issue-bar-inner { max-width: 1240px; margin: 0 auto; padding: var(--s-3) var(--s-4); display: flex; align-items: center; justify-content: space-between; gap: var(--s-4); flex-wrap: wrap; }
.issue-id { display: flex; gap: var(--s-3); align-items: baseline; }
.graph-map { display: block; width: 100%; height: auto; margin-top: var(--s-6); }
.graph-edge { stroke: var(--border-strong); stroke-width: 1; }
.graph-node.up { fill: color-mix(in srgb, var(--accent) calc(50% + 50% * var(--b)), var(--text-faint)); }
.graph-node.down { fill: color-mix(in srgb, var(--text-dim) calc(50% + 50% * var(--b)), var(--text-faint)); }
.graph-node.mixed { fill: none; stroke: var(--text-dim); stroke-width: 1.5; }
.graph-label { fill: var(--text); font-family: var(--font-mono); font-size: calc(12px * var(--type-scale)); }
.read-progress { position: fixed; top: calc(var(--bar-h) - 3px); left: 0; right: 0; z-index: 11; max-width: 1240px; height: 3px; margin: 0 auto; padding: 0 var(--s-4); display: flex; pointer-events: none; }
.read-progress span { flex: 1 1 0; min-width: 0; background: var(--border-strong); }
.read-progress span + span { border-left: 1px solid var(--bg); }
.read-progress i { display: block; width: 0; height: 100%; background: var(--accent); }
[hidden] { display: none !important; }
/* Tap area (spec section 4): a target drawn under 44px keeps its size, and this transparent box takes the taps around it. */
.btn.sm, .brand, .site-nav a, details.more summary { position: relative; }
.btn.sm::after, .brand::after, .site-nav a::after { content: ""; position: absolute; inset: min(0px, calc((100% - 44px) / 2)); }
details.more summary::after { content: ""; position: absolute; inset: calc(-1 * var(--s-1)) 0 min(0px, calc(100% + var(--s-1) - 44px)); }
@media (max-width: 720px) { .site-nav { gap: var(--s-3); } .brand-name { display: none; } .site-nav .label { letter-spacing: .08em; } }
:focus-visible { outline: 1px solid var(--accent); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; animation: none !important; scroll-behavior: auto !important; } }

body {
  font-family: var(--font-sans);
  font-feature-settings: "ss01", "ss02", "cv11";
  background: var(--bg);
  /* The digest's grid. This surface dropped `background-attachment: fixed`
     first — iOS Safari treats it inconsistently on a touch surface — and the
     digest templates followed on 2026-08-30 for the reason that generalises:
     a fixed-attachment gradient cannot be composited, so every scroll frame
     repaints the whole viewport. The two now agree. */
  background-image:
    linear-gradient(var(--grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid) 1px, transparent 1px);
  background-size: 32px 32px, 32px 32px;
  color: var(--text);
}
